CREATE FUNCTION "geography"."scheme_features_feature_type_id" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."feature_type_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "reference"."values" v
    JOIN "reference"."schemes" s ON s."id" = v."scheme_id"
    WHERE v."id" = NEW."feature_type_id" AND s."code" = 'geo.feature.kind'
    FOR SHARE OF v, s
  ) THEN
    RAISE EXCEPTION 'referenced value belongs to a different scheme' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

CREATE TRIGGER "scheme_features_feature_type_id"
BEFORE INSERT OR UPDATE OF "feature_type_id" ON "geography"."features" FOR EACH ROW
EXECUTE FUNCTION "geography"."scheme_features_feature_type_id" ();

CREATE FUNCTION "geography"."scheme_features_feature_type_id_membership" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."scheme_id" IS DISTINCT FROM OLD."scheme_id" AND EXISTS (
    SELECT 1 FROM "geography"."features" t WHERE t."feature_type_id" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'cannot move a value used by a scheme-constrained link' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

