CREATE VIEW "geography"."current_geometries" AS
SELECT
    "area" AS "area",
    "centroid" AS "centroid",
    "feature_id" AS "feature_id",
    "geometry" AS "geometry",
    "id" AS "id"
FROM
    "geography"."geometries"
WHERE
    "valid_until" IS NULL;

