CREATE FUNCTION "reference"."scheme_countries_subregion_id_membership" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF NEW."scheme_id" IS DISTINCT FROM OLD."scheme_id" AND EXISTS (
    SELECT 1 FROM "reference"."countries" t WHERE t."subregion_id" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'cannot move a value used by a scheme-constrained link' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

CREATE TRIGGER "reference_scheme_countries_subregion_id_membership"
BEFORE UPDATE OF "scheme_id" ON "reference"."values" FOR EACH ROW
EXECUTE FUNCTION "reference"."scheme_countries_subregion_id_membership" ();

CREATE FUNCTION "reference"."scheme_countries_subregion_id_code" () RETURNS trigger LANGUAGE plpgsql AS $scheme$
BEGIN
  IF OLD."code" = 'geo.subregion' AND NEW."code" IS DISTINCT FROM OLD."code" AND EXISTS (
    SELECT 1 FROM "reference"."countries" t
    JOIN "reference"."values" v ON v."id" = t."subregion_id"
    WHERE v."scheme_id" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'cannot rename a scheme used by a scheme-constrained link' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$scheme$;

CREATE TRIGGER "reference_scheme_countries_subregion_id_code"
BEFORE UPDATE OF "code" ON "reference"."schemes" FOR EACH ROW
EXECUTE FUNCTION "reference"."scheme_countries_subregion_id_code" ();
